---@class OverseaManageCafeCattyStarNode
local OverseaManageCafeCattyStarNode = Class('OverseaManageCafeCattyStarNode')
local StarCount = 5
local StarCellPath = "Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OverseaManageCafeCattyStarNodeCell"
function OverseaManageCafeCattyStarNode:__init()
    self.starCellEnv = {}
end

function OverseaManageCafeCattyStarNode:__delete()
    self.starCellEnv = nil
end

function OverseaManageCafeCattyStarNode:Awake()
    self:InitNodeEnv()
end

function OverseaManageCafeCattyStarNode:InitNodeEnv()
    for i = 1, StarCount do
        local node = self["BtnStar"..i]
        if node then
            local env = CfUtils.GetLuaScr(node,StarCellPath)
            if env then
                env:SetStarIndex(i)
                env:SetStarCellCallBack(Bind(self,self.OnStarCellClick))
                self.starCellEnv[i] = env
            end
        end
    end
end

function OverseaManageCafeCattyStarNode:SetTipPos(pos)

end

function OverseaManageCafeCattyStarNode:OnStarCellClick()
    printError("OnStarCellClick")
end

function OverseaManageCafeCattyStarNode:RefreshShow(isToMax)
    if isToMax then
        for i = 1, #self.starCellEnv do
            self.starCellEnv[i]:SetFullStarShow()
        end
    else
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local curLevel = component:GetMaidCoffeeLevel()
        local curStarLevel = component:GetMaidCoffeeCattyStarLevel()
        local lightCircle = curLevel - (curStarLevel * 5)

        for i = 1, #self.starCellEnv do
            if i > curStarLevel + 1 then
                ---后面的星星
                self.starCellEnv[i]:SetNextStarShow()
            elseif i == curStarLevel + 1 then
                ---当前正在升级的星星
                self.curStar = i
                self.starCellEnv[i]:SetCurStarShow(lightCircle)
            else
                ---满星
                self.starCellEnv[i]:SetFullStarShow()
            end
        end
    end
end

function OverseaManageCafeCattyStarNode:PlayCurStarAni()
    if self.curStar and self.AniRoot then
        local aniName = string.format("OverseaManageCafeCattyLetterDialogStarGroup_Get%s",self.curStar)
        self.starCellEnv[self.curStar]:SetStarGetStatus(true)
        self.AniRoot:Play(aniName)
    end
end

function OverseaManageCafeCattyStarNode:Start()
end

function OverseaManageCafeCattyStarNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManageCafeCattyStarNode